// Arma la respuesta de /geo-dashboard a partir de las filas de la hoja
// Resultados. Sin dependencias: build.mjs lo pega en el nodo Code «Dashboard».
//
// Las filas llegan de Google Sheets como texto: «TRUE», «0,25», «3». Por eso
// todo pasa por aBool y aNum antes de sumar.

function aBool(v) {
  if (typeof v === 'boolean') return v;
  return ['true', 'verdadero', '1', 'si', 'sí', 'x'].includes(String(v || '').trim().toLowerCase());
}

function aNum(v) {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  const s = String(v == null ? '' : v).trim().replace(',', '.');
  if (s === '') return null;
  const n = Number(s);
  return isFinite(n) ? n : null;
}

function aLista(v) {
  if (Array.isArray(v)) return v;
  return String(v || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);
}

function pct(a, b) {
  return b ? Math.round((a / b) * 1000) / 10 : 0;
}

function promedio(xs) {
  const v = xs.filter(x => x !== null && x !== undefined);
  return v.length ? Math.round((v.reduce((s, x) => s + x, 0) / v.length) * 100) / 100 : null;
}

function normalizarFila(f) {
  return {
    run_id: String(f.run_id || ''),
    fecha: String(f.fecha || '').slice(0, 10),
    timestamp: String(f.timestamp || ''),
    prompt_id: String(f.prompt_id || ''),
    proyecto: String(f.proyecto || '').trim() || 'Sin proyecto',
    prompt: String(f.prompt || ''),
    motor: String(f.motor || ''),
    estado: String(f.estado || '').trim(),
    disponible: f.estado !== undefined ? String(f.estado).trim() === 'ok' : aBool(f.disponible),
    menciona: aBool(f.menciona_bcp !== undefined ? f.menciona_bcp : f.menciona),
    posicion: aNum(f.posicion_bcp !== undefined ? f.posicion_bcp : f.posicion),
    sentimiento: aNum(f.sentimiento),
    citado: aBool(f.citado_bcp !== undefined ? f.citado_bcp : f.citado),
    marcas: aLista(f.marcas_mencionadas !== undefined ? f.marcas_mencionadas : f.marcas),
    fuentes: aLista(f.fuentes),
    respuesta: String(f.respuesta || ''),
    error: String(f.error || ''),
    n_menciones_bcp: aNum(f.n_menciones_bcp),
    n_menciones_bancos: aNum(f.n_menciones_bancos),
    categoria: String(f.categoria || ''),
    detalle_marcas: String(f.detalle_marcas || ''),
    sov_bcp: aNum(f.sov_bcp)
  };
}

// Las métricas de un grupo de filas. Las filas con error no cuentan: si a un
// motor se le acabó el saldo, no es que no nos mencione.
function metricas(filas) {
  const validas = filas.filter(f => !f.error);
  const menc = validas.filter(f => f.menciona);
  return {
    total_respuestas: validas.length,
    menciones: menc.length,
    share_of_model: pct(menc.length, validas.length),
    citaciones: validas.filter(f => f.citado).length,
    tasa_citacion: pct(validas.filter(f => f.citado).length, validas.length),
    sentimiento_promedio: promedio(menc.map(f => f.sentimiento)),
    posicion_promedio: promedio(menc.map(f => f.posicion))
  };
}

// Variación en puntos porcentuales: el último día con datos contra el anterior.
function variacion(filas) {
  const fechas = [...new Set(filas.filter(f => !f.error).map(f => f.fecha))].sort();
  if (fechas.length < 2) return null;
  const ult = metricas(filas.filter(f => f.fecha === fechas[fechas.length - 1])).share_of_model;
  const ant = metricas(filas.filter(f => f.fecha === fechas[fechas.length - 2])).share_of_model;
  return Math.round((ult - ant) * 10) / 10;
}

function construirDashboard(filasCrudas, filtros, config) {
  filtros = filtros || {};
  const motores = config.motores;
  const marcaPropia = config.marca.nombre;
  const dominiosPropios = (config.marca.dominios || []).map(d => d.toLowerCase());
  const esPropio = d => dominiosPropios.some(p => d === p || d.endsWith('.' + p));

  const todas = filasCrudas
    .filter(f => f && (f.motor || f.prompt_id))
    .map(normalizarFila)
    .filter(f => motores.some(m => m.key === f.motor));

  const filas = todas.filter(f =>
    (!filtros.proyecto || f.proyecto === filtros.proyecto) &&
    (!filtros.motor || f.motor === filtros.motor) &&
    (!filtros.prompt_id || f.prompt_id === filtros.prompt_id) &&
    (!filtros.desde || f.fecha >= filtros.desde) &&
    (!filtros.hasta || f.fecha <= filtros.hasta)
  );

  const base = { motores, filtros };
  if (!filas.length) {
    return Object.assign(base, {
      vacio: !todas.length,
      kpis: Object.assign(metricas([]), {
        var_share_of_model: null, presencia_ai_overview: null,
        ultima_corrida: todas.length ? todas.map(f => f.timestamp || f.fecha).sort().pop() : null
      }),
      por_motor: [], tendencia: [], competidores: [], fuentes: [], proyectos: [], prompts: [], respuestas: []
    });
  }

  const validas = filas.filter(f => !f.error);
  const aio = validas.filter(f => f.motor === 'ai_overview');

  const kpis = Object.assign(metricas(filas), {
    var_share_of_model: variacion(filas),
    presencia_ai_overview: aio.length ? pct(aio.filter(f => f.disponible).length, aio.length) : null,
    ultima_corrida: filas.map(f => f.timestamp || f.fecha).sort().pop()
  });

  const por_motor = motores.map(m => {
    const fm = filas.filter(f => f.motor === m.key);
    const x = metricas(fm);
    return {
      motor: m.key, label: m.label,
      share_of_model: x.share_of_model, var_share_of_model: variacion(fm),
      menciones: x.menciones, total_respuestas: x.total_respuestas, citaciones: x.citaciones,
      sentimiento_promedio: x.sentimiento_promedio, posicion_promedio: x.posicion_promedio
    };
  });

  const fechas = [...new Set(validas.map(f => f.fecha))].sort();
  const tendencia = fechas.map(fecha => {
    const fd = validas.filter(f => f.fecha === fecha);
    const punto = { fecha };
    for (const m of motores) {
      const fm = fd.filter(f => f.motor === m.key);
      punto[m.key] = fm.length ? metricas(fm).share_of_model : null;
    }
    punto.total = metricas(fd).share_of_model;
    return punto;
  });

  const nombres = [marcaPropia].concat((config.competidores || []).map(c => c.nombre));
  const competidores = nombres
    .map(marca => {
      const n = validas.filter(f => f.marcas.includes(marca)).length;
      return { marca, menciones: n, share_of_model: pct(n, validas.length), es_bcp: marca === marcaPropia };
    })
    .sort((a, b) => b.menciones - a.menciones || (b.es_bcp ? 1 : 0) - (a.es_bcp ? 1 : 0))
    .map((c, i) => Object.assign({ ranking: i + 1 }, c));

  const conteo = {};
  for (const f of validas) for (const d of f.fuentes) conteo[d] = (conteo[d] || 0) + 1;
  const fuentes = Object.keys(conteo)
    .map(dominio => ({ dominio, citas: conteo[dominio], es_bcp: esPropio(dominio) }))
    .sort((a, b) => b.citas - a.citas)
    .slice(0, 30);

  const nombresProyectos = [...new Set(filas.map(f => f.proyecto))].sort();
  const proyectos = nombresProyectos.map(proyecto => {
    const fp = filas.filter(f => f.proyecto === proyecto);
    const x = metricas(fp);
    return {
      proyecto, prompts: new Set(fp.map(f => f.prompt_id)).size,
      share_of_model: x.share_of_model, var_share_of_model: variacion(fp), menciones: x.menciones
    };
  });

  // La matriz prompt × motor muestra la última respuesta válida de cada motor.
  const idsPrompts = [...new Set(filas.map(f => f.prompt_id))];
  const prompts = idsPrompts.map(id => {
    const fp = filas.filter(f => f.prompt_id === id);
    const ultima = fp.map(f => f.fecha).sort().pop();
    const mot = {};
    for (const m of motores) {
      const r = fp.filter(f => f.motor === m.key && !f.error)
        .sort((a, b) => (a.timestamp || a.fecha).localeCompare(b.timestamp || b.fecha)).pop();
      mot[m.key] = r
        ? { menciona: r.menciona, posicion: r.posicion, sentimiento: r.sentimiento, citado: r.citado, marcas: r.marcas, fecha: r.fecha, disponible: r.disponible }
        : null;
    }
    const recientes = fp.filter(f => f.fecha === ultima);
    return {
      prompt_id: id, prompt: fp[fp.length - 1].prompt, proyecto: fp[fp.length - 1].proyecto,
      share_of_model: metricas(recientes).share_of_model, ultima_fecha: ultima, motores: mot
    };
  });

  let respuestas = [];
  if (filtros.proyecto || filtros.prompt_id) {
    respuestas = filas
      .slice()
      .sort((a, b) => (b.timestamp || b.fecha).localeCompare(a.timestamp || a.fecha))
      .slice(0, 300)
      .map(f => ({
        fecha: f.fecha, timestamp: f.timestamp, motor: f.motor, prompt_id: f.prompt_id, prompt: f.prompt,
        menciona: f.menciona, posicion: f.posicion, sentimiento: f.sentimiento, citado: f.citado,
        disponible: f.disponible, marcas: f.marcas, fuentes: f.fuentes, respuesta: f.respuesta, error: f.error
      }));
  }

  return Object.assign(base, { vacio: false, kpis, por_motor, tendencia, competidores, fuentes, proyectos, prompts, respuestas });
}

const q = $('Webhook geo-dashboard').first().json.query || {};
const filtros = {};
for (const k of ['proyecto', 'motor', 'desde', 'hasta', 'prompt_id']) if (q[k]) filtros[k] = String(q[k]);
return [{ json: construirDashboard(leerHojas($input.first().json).resultados, filtros, Object.assign({ motores: MOTORES }, CONFIG)) }];

const SHEET_ID = 'PEGA_AQUI_EL_ID_DE_TU_GOOGLE_SHEET';
// El Google Sheet, organizado como lo usa el equipo de BCP:
//   · una pestaña por proyecto con sus prompts (Marca, Ahorros, Cards…)
//   · una pestaña por día de medición con los resultados (2026-10-21, …)
//   · las que empiezan con «_» son de sistema (respaldos, notas) y se ignoran.
// Se lee y escribe con la API de Google Sheets (nodos HTTP con la credencial de
// Sheets); aquí solo se arman las peticiones y se interpretan las respuestas.
// Sin dependencias: build.mjs lo pega en los nodos Code que lo necesitan.

const SHEETS_API = 'https://sheets.googleapis.com/v4/spreadsheets/' + SHEET_ID;

// Encabezados de las pestañas de proyecto (los del Excel original de BCP, más
// id, activo y fecha para poder gestionarlos desde el front).
const COLUMNAS_PROMPTS = ['id', 'Categoría', 'Intención de Búsqueda', 'Prompt', 'Activo', 'Fecha de creación'];
const COLUMNAS_RESULTADOS = ['run_id', 'fecha', 'timestamp', 'prompt_id', 'proyecto', 'categoria', 'prompt', 'motor', 'estado',
  'menciona_bcp', 'posicion_bcp', 'sentimiento', 'marcas_mencionadas', 'fuentes', 'citado_bcp', 'error', 'respuesta',
  'n_menciones_bcp', 'n_menciones_bancos', 'detalle_marcas', 'sov_bcp'];

function esPestanaFecha(titulo) { return /^\d{4}-\d{2}-\d{2}$/.test(String(titulo || '').trim()); }
function esPestanaSistema(titulo) { return String(titulo || '').trim().startsWith('_'); }
function esPestanaProyecto(titulo) { return !esPestanaFecha(titulo) && !esPestanaSistema(titulo) && String(titulo || '').trim() !== ''; }

function pestanas(meta) {
  return ((meta && meta.sheets) || []).map(s => s.properties).filter(Boolean)
    .map(p => ({ id: p.sheetId, titulo: p.title, indice: p.index }));
}

// Rango A1 de una pestaña, con el nombre entre comillas (acepta espacios y tildes).
function rango(titulo, celdas) {
  return "'" + String(titulo).replace(/'/g, "''") + "'!" + celdas;
}

// Cuerpo de values:batchGetByDataFilter para leer varias pestañas en una llamada.
// desde (AAAA-MM-DD): solo las pestañas de resultados desde esa fecha.
function cuerpoLectura(meta, { prompts = false, resultadosDesde = null } = {}) {
  const filtros = [];
  for (const p of pestanas(meta)) {
    if (prompts && esPestanaProyecto(p.titulo)) filtros.push({ a1Range: rango(p.titulo, 'A:F') });
    if (resultadosDesde && esPestanaFecha(p.titulo) && p.titulo >= resultadosDesde) filtros.push({ a1Range: rango(p.titulo, 'A:U') });
  }
  // La API no acepta una lista vacía: sin nada que leer, se pide A1 de la primera pestaña.
  const primera = pestanas(meta)[0];
  if (!filtros.length && primera) filtros.push({ a1Range: rango(primera.titulo, 'A1:A1') });
  return { dataFilters: filtros, majorDimension: 'ROWS', valueRenderOption: 'UNFORMATTED_VALUE' };
}

function tituloDeRango(r) {
  const m = String(r || '').match(/^'((?:[^']|'')*)'!/) || String(r || '').match(/^([^!]+)!/);
  return m ? m[1].replace(/''/g, "'") : '';
}

function claveColumna(c) {
  const k = String(c || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
  if (k === 'id') return 'id';
  if (k.startsWith('categ')) return 'categoria';
  if (k.startsWith('intenc')) return 'intencion';
  if (k.startsWith('prompt')) return 'prompt';
  if (k.startsWith('activo')) return 'activo';
  if (k.startsWith('fecha')) return 'fecha_creacion';
  return '';
}

// Respuesta de batchGetByDataFilter → {prompts: [...], resultados: [...]}.
// Cada prompt lleva su pestaña (= proyecto) y su número de fila.
function leerHojas(respuesta) {
  const prompts = [];
  const resultados = [];
  for (const vr of (respuesta && respuesta.valueRanges) || []) {
    const v = vr.valueRange || vr;
    const titulo = tituloDeRango(v.range);
    const filas = v.values || [];
    if (!filas.length) continue;
    if (esPestanaFecha(titulo)) {
      const cab = filas[0].map(String);
      filas.slice(1).forEach(f => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = {};
        cab.forEach((c, i) => { o[c] = f[i] === undefined ? '' : f[i]; });
        resultados.push(o);
      });
    } else if (esPestanaProyecto(titulo)) {
      const cab = filas[0].map(claveColumna);
      filas.slice(1).forEach((f, i) => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = { proyecto: titulo, _fila: i + 2 };
        cab.forEach((c, j) => { if (c) o[c] = f[j] === undefined ? '' : f[j]; });
        if (o.fecha_creacion !== undefined) o.fecha_creacion = fechaTexto(o.fecha_creacion);
        prompts.push(o);
      });
    }
  }
  return { prompts, resultados };
}

// Las fechas pueden volver como número de serie de Sheets (UNFORMATTED_VALUE).
function fechaTexto(v) {
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    return new Date(Date.UTC(1899, 11, 30) + v * 864e5).toISOString().slice(0, 10);
  }
  return String(v || '');
}

function valoresPrompt(p) {
  return [p.id, p.categoria || '', p.intencion || '', p.prompt || '', p.activo === false ? 'FALSE' : 'TRUE', p.fecha_creacion || ''];
}

function valoresResultado(f) {
  return COLUMNAS_RESULTADOS.map(c => {
    const v = f[c];
    return v === undefined || v === null ? '' : typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : v;
  });
}

// ─── Peticiones a la API de Sheets ─────────────────────────────────────────
const pedidoSheets = (method, ruta, body) => ({ method, url: SHEETS_API + ruta, body });
const crearPestana = (titulo, indice) =>
  pedidoSheets('POST', ':batchUpdate', { requests: [{ addSheet: { properties: Object.assign({ title: titulo }, indice === undefined ? {} : { index: indice }) } }] });
const escribir = (titulo, desde, valores) =>
  pedidoSheets('PUT', '/values/' + encodeURIComponent(rango(titulo, desde)) + '?valueInputOption=RAW', { values: valores });
const agregar = (titulo, valores) =>
  pedidoSheets('POST', '/values/' + encodeURIComponent(rango(titulo, 'A1')) + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS', { values: valores });
const borrarFila = (idPestana, fila) =>
  pedidoSheets('POST', ':batchUpdate', { requests: [{ deleteDimension: { range: { sheetId: idPestana, dimension: 'ROWS', startIndex: fila - 1, endIndex: fila } } }] });

// Crear, editar, activar/desactivar, mover de proyecto o eliminar un prompt.
// guardado: lo que devuelve prepararGuardado (prompts.js).
// → {ok, status, respuesta, peticiones}
function planGuardarPrompt(guardado, prompts, meta) {
  if (!guardado.ok) return { ok: false, status: 400, respuesta: { ok: false, error: guardado.error }, peticiones: [] };
  const tabs = pestanas(meta);
  const tab = titulo => tabs.find(t => t.titulo === titulo);
  const fila = guardado.fila;
  const actual = prompts.find(p => String(p.id).trim() === fila.id);
  const proyectosAlFinal = tabs.filter(t => esPestanaProyecto(t.titulo)).length;
  const asegurarPestana = (titulo, pet) => {
    if (!tab(titulo)) {
      pet.push(crearPestana(titulo, proyectosAlFinal));
      pet.push(escribir(titulo, 'A1', [COLUMNAS_PROMPTS]));
    }
  };

  if (guardado.accion === 'eliminar') {
    if (!actual) return { ok: false, status: 404, respuesta: { ok: false, error: 'No existe el prompt ' + fila.id }, peticiones: [] };
    return { ok: true, status: 200, respuesta: { ok: true, accion: 'eliminar', id: fila.id }, peticiones: [borrarFila(tab(actual.proyecto).id, actual._fila)] };
  }

  if (guardado.accion === 'editar') {
    if (!actual) return { ok: false, status: 404, respuesta: { ok: false, error: 'No existe el prompt ' + fila.id }, peticiones: [] };
    const nuevo = Object.assign({}, normalizarPrompt(actual), fila);
    const pet = [];
    if (nuevo.proyecto === actual.proyecto) {
      pet.push(escribir(actual.proyecto, 'A' + actual._fila + ':F' + actual._fila, [valoresPrompt(nuevo)]));
    } else {
      // Cambio de proyecto: se agrega en la pestaña nueva y se borra de la vieja.
      asegurarPestana(nuevo.proyecto, pet);
      pet.push(agregar(nuevo.proyecto, [valoresPrompt(nuevo)]));
      pet.push(borrarFila(tab(actual.proyecto).id, actual._fila));
    }
    return { ok: true, status: 200, respuesta: { ok: true, accion: 'editar', prompt: limpio(nuevo) }, peticiones: pet };
  }

  // Crear: un proyecto nuevo crea su pestaña.
  const nuevo = normalizarPrompt(fila);
  const pet = [];
  asegurarPestana(nuevo.proyecto, pet);
  pet.push(agregar(nuevo.proyecto, [valoresPrompt(nuevo)]));
  return { ok: true, status: 200, respuesta: { ok: true, accion: 'crear', prompt: limpio(nuevo) }, peticiones: pet };
}

function limpio(p) {
  const o = {};
  for (const k of Object.keys(p)) if (!k.startsWith('_')) o[k] = p[k];
  return o;
}

// Guardar las filas de una corrida en la pestaña del día (se crea si no está,
// justo después de las pestañas de proyecto, para que la más reciente quede primero).
function planGuardarResultados(filas, meta) {
  const porFecha = new Map();
  for (const f of filas) {
    if (!porFecha.has(f.fecha)) porFecha.set(f.fecha, []);
    porFecha.get(f.fecha).push(valoresResultado(f));
  }
  const tabs = pestanas(meta);
  const proyectos = tabs.filter(t => esPestanaProyecto(t.titulo)).length;
  const pet = [];
  for (const [fecha, valores] of porFecha) {
    if (tabs.some(t => t.titulo === fecha)) pet.push(agregar(fecha, valores));
    else {
      pet.push(crearPestana(fecha, proyectos));
      pet.push(escribir(fecha, 'A1', [COLUMNAS_RESULTADOS].concat(valores)));
    }
  }
  return pet;
}

return [{ json: { cuerpo: cuerpoLectura($input.first().json, { prompts: true }) } }];

